import unittest
import job

class JobTests(unittest.TestCase):
    def test_valid_transitions(self):
        self.assertEqual(job.transition('idle', 'start'), 'running')
        self.assertEqual(job.transition('running', 'finish'), 'done')
        self.assertEqual(job.transition('running', 'fail'), 'failed')

    def test_invalid_transition_raises(self):
        with self.assertRaises(ValueError):
            job.transition('done', 'start')

if __name__ == '__main__':
    unittest.main()

