TRANSITIONS = {
    ('idle', 'start'): 'running',
    ('running', 'finish'): 'done',
    ('running', 'fail'): 'failed',
}


def transition(state, event):
    key = (state, event)
    if key not in TRANSITIONS:
        raise ValueError(f'invalid transition {state!r} -> {event!r}')
    return TRANSITIONS[key]

