import unittest
import orders

class OrderTests(unittest.TestCase):
    def test_normalizes_once_at_boundary(self):
        parsed = orders.parse_order({'division': ' Retail ', 'sku': ' hj-40 '})
        self.assertEqual(parsed, {'division': 'retail', 'sku': 'HJ-40'})
        self.assertEqual(orders.route_order(parsed), 'retail:HJ-40')
        self.assertEqual(orders.format_label(parsed), 'retail/HJ-40')

if __name__ == '__main__':
    unittest.main()

